public class MutableDateTime_addYears_TriageGen2Test {







    @Test
    public void testAddYearsLeapYearToNonLeapYear() {
        // Test leap year edge case: Feb 29th + 1 year should result in Feb 28th
        MutableDateTime dt = new MutableDateTime(2020, 2, 29, 10, 0, 0, 0);
        dt.addYears(1);
        assertEquals(2021, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(28, dt.getDayOfMonth());
    }






