public class MutableDateTime_addYears_TriageGen2Test {













    @Test
    public void testAddYearsWithTimePreservation() {
        // Ensure hours, minutes, seconds, and millis are preserved
        MutableDateTime dt = new MutableDateTime(2000, 1, 1, 23, 59, 59, 999);
        dt.addYears(10);
        assertEquals(2010, dt.getYear());
        assertEquals(23, dt.getHourOfDay());
        assertEquals(59, dt.getMinuteOfHour());
        assertEquals(59, dt.getSecondOfMinute());
        assertEquals(999, dt.getMillisOfSecond());
    }
}
